from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in g]
    segs=[]; anchors=set()
    # horizontal runs
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]!=bg:
                col=g[r][c]; c0=c
                while c<W and g[r][c]==col: c+=1
                if c-c0>1: segs.append((r,c0,c,'h',col)); anchors.add(col)
            else: c+=1
    # vertical runs
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]!=bg:
                col=g[r][c]; r0=r
                while r<H and g[r][c]==col: r+=1
                if r-r0>1: segs.append((c,r0,r-1,'v',col)); anchors.add(col)
            else: r+=1
    marker=None
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and g[r][c] not in anchors: marker=g[r][c]
    for seg in segs:
        a,b,e,orient,col=seg
        if orient=='v':
            dc = 1 if a<W/2 else -1
            for r in range(b,e+1):
                cc=a+dc
                while 0<=cc<W:
                    v=g[r][cc]
                    if v==col: break
                    if v==marker: out[r][cc]=4; break
                    if v!=bg: break
                    out[r][cc]=marker; cc+=dc
        else:
            dr = 1 if a<H/2 else -1
            for c in range(b,e+1):
                rr=a+dr
                while 0<=rr<H:
                    v=g[rr][c]
                    if v==col: break
                    if v==marker: out[rr][c]=4; break
                    if v!=bg: break
                    out[rr][c]=marker; rr+=dr
    for r in range(H):
        for c in range(W):
            if g[r][c]==marker: out[r][c]=4
    return out

